{
  "name": "@marcelorodrigo/opencode-spring-crew",
  "version": "0.3.2",
  "description": "Spring Boot development agents for opencode: Orchestrator, Rubber Duck, Architect, Implementer, Code Reviewer",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "engines": {
    "node": ">=24.0.0"
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "tsup",
    "dev": "tsup --watch",
    "typecheck": "tsc --noEmit"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "spring-boot",
    "clean-architecture"
  ],
  "author": "Marcelo Rodrigo",
  "contributors": [
    "Lucas Germani"
  ],
  "license": "MIT",
  "homepage": "https://github.com/marcelorodrigo/spring-crew-plugin",
  "devDependencies": {
    "@opencode-ai/plugin": "1.14.20",
    "@opencode-ai/sdk": "1.14.20",
    "tsup": "^8.0.0",
    "typescript": "^5.7.0"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/marcelorodrigo/spring-crew-plugin.git"
  }
}
